 PnrRoundGuard87 guard;need(handle&&tree_handle&&squeezing&&mean&&modes&&draws&&selected&&normalized_rates&&statistics&&length>=0&&length<=7&&count>=0,"PureTree89 probe arguments");auto& c=*static_cast<ClickModel70*>(handle);auto& tr=*static_cast<BlockTree87*>(tree_handle);int n=c.model->n,d=2*n,m=c.model->m;State73 state{Real::Zero(d,d),Vector(d),{}};Vector t(n);for(int i=0;i<n;++i){t[i]=squeezing[i];need(std::abs(t[i])<1,"PureTree89 squeeze");state.x(i,i)=-t[i]/(1+t[i]);state.x(n+i,n+i)=t[i]/(1-t[i]);}for(int i=0;i<d;++i)state.mean[i]=mean[i];for(int i=0;i<length;++i){need(modes[i]>=0&&modes[i]<m,"PureTree89 mode");state.factors.push_back(modes[i]);}auto ids=state.factors;ids.push_back(0);LD73 total=0;std::vector<LD73> rates(m);for(int i=0;i<m;++i){ids.back()=i;rates[i]=pure_norm74(c,t,state.mean.cast<LD73>(),ids,1);total+=rates[i];}need(total>0,"PureTree89 empty rate");for(int i=0;i<m;++i)normalized_rates[i]=double(rates[i]/total);BlockTrace87 trace;for(int i=0;i<count;++i){need(draws[i]>=0&&draws[i]<1,"PureTree89 uniform");selected[2*i]=pure_detector74(c,state,t,draws[i]);selected[2*i+1]=detector89(c,state,draws[i],tr,trace,&t);}statistics[0]=trace.calls;statistics[1]=trace.fallbacks;statistics[2]=trace.ondemand;statistics[3]=trace.leaves;return 0;
